/** A failed server function call. */
export class ServerFunctionError extends Error {
  /** The HTTP status: 400 invalid input, 401/403 refused, 404 not found, 500 failed. */
  status: number;
  /** The schema's issues when the input was invalid. */
  issues?: Array<{ message: string; path?: PropertyKey[] }>;
  /** The server answered with a redirect (e.g. an auth guard). */
  redirected: boolean;
}
/** The browser stub for a server function (generated by the build). */
export function serverFunction<Input = unknown, Output = unknown>(
  endpoint: string,
  kind: "query" | "action",
): (input: Input, options?: { signal?: AbortSignal }) => Promise<Output>;
